package models

import "go.mongodb.org/mongo-driver/bson/primitive"

type SourceClassification string

const (
	SourceIndependent   SourceClassification = "independent"
	SourceRegisteredERP SourceClassification = "registered_erp"
	SourceUnresolvedERP SourceClassification = "unresolved_erp"
)

type ERPSourcePhase string

const (
	ERPSourceIdle       ERPSourcePhase = "idle"
	ERPSourceSyncing    ERPSourcePhase = "syncing"
	ERPSourceRecovering ERPSourcePhase = "recovering"
)

// ERPSource contains references and identities only, never a DSN or secret value.
// SourceID is generated by registration and is never reused or changed.
type ERPSource struct {
	SchemaVersion                  int                     `bson:"schema_version"`
	SourceID                       string                  `bson:"source_id"`
	ConfigRevision                 int64                   `bson:"config_revision"`
	StateRevision                  int64                   `bson:"state_revision"`
	EnvironmentRef                 string                  `bson:"environment_ref"`
	PhysicalDatabase               string                  `bson:"physical_database"`
	ApprovedEndpointAliases        []string                `bson:"approved_endpoint_aliases"`        // endpoint-only fingerprints; unique across sources
	ApprovedConnectionFingerprints []string                `bson:"approved_connection_fingerprints"` // includes driver and approved reader identity
	ReaderRoleRefs                 []string                `bson:"reader_role_refs"`
	WriterRoleRef                  string                  `bson:"writer_role_ref"`
	DeploymentUID                  uint32                  `bson:"deployment_uid"`
	LockPath                       string                  `bson:"lock_path"`
	LockDevice                     uint64                  `bson:"lock_device"`
	LockInode                      uint64                  `bson:"lock_inode"`
	ComponentManifestRef           string                  `bson:"component_manifest_ref"`
	SecretInjectionRef             string                  `bson:"secret_injection_ref"`
	ChatBindings                   []ERPChatBinding        `bson:"chat_bindings"`
	ViewAccountIDs                 []primitive.ObjectID    `bson:"view_account_ids"`
	SyncOperatorAccountIDs         []primitive.ObjectID    `bson:"sync_operator_account_ids"`
	ShopScope                      []string                `bson:"shop_scope"`
	OrderSourceByShop              map[string]string       `bson:"order_source_by_shop"`
	ApprovalRefs                   map[string]string       `bson:"approval_refs"`
	Phase                          ERPSourcePhase          `bson:"phase"`
	ActiveOperation                *ERPSourceOperation     `bson:"active_operation"`
	LastReleasedOperationID        string                  `bson:"last_released_operation_id"`
	RecoveryVerifiedInstanceID     string                  `bson:"recovery_verified_instance_id"`
	RegistrationReceipt            *ERPRegistrationReceipt `bson:"registration_receipt,omitempty"`
}

type ERPChatBinding struct {
	ChatID                primitive.ObjectID `bson:"chat_id"`
	OwnerID               primitive.ObjectID `bson:"owner_id"`
	ConnectionFingerprint string             `bson:"connection_fingerprint"`
	BindingRevision       int64              `bson:"binding_revision"`
	OperationID           string             `bson:"operation_id"`
	Confirmed             bool               `bson:"confirmed"`
}

// Operation is a durable recovery veto, not another busy authority.
type ERPSourceOperation struct {
	OperationID          string             `bson:"operation_id"`
	Kind                 string             `bson:"kind"`
	OwnerID              primitive.ObjectID `bson:"owner_id,omitempty"`
	ChatID               primitive.ObjectID `bson:"chat_id,omitempty"`
	RequestID            string             `bson:"request_id"`
	JobID                string             `bson:"job_id"`
	ConfigRevision       int64              `bson:"config_revision"`
	ComponentManifestRef string             `bson:"component_manifest_ref"`
	InstanceID           string             `bson:"instance_id"`
	BootID               string             `bson:"boot_id"`
}

// RegistrationReceipt records an offline intent and observed CAS results. It
// never grants execution or substitutes for either confirmed binding half.
type ERPRegistrationReceipt struct {
	Revision                    int64              `bson:"revision" json:"revision"`
	RequestID                   string             `bson:"request_id" json:"request_id"`
	InputSHA256                 string             `bson:"input_sha256" json:"input_sha256"`
	ExistingChatID              primitive.ObjectID `bson:"existing_chat_id" json:"existing_chat_id"`
	OwnerID                     primitive.ObjectID `bson:"owner_id" json:"owner_id"`
	BindingOperationID          string             `bson:"binding_operation_id" json:"binding_operation_id"`
	BeforeBindingRevision       int64              `bson:"before_binding_revision" json:"before_binding_revision"`
	AfterBindingRevision        int64              `bson:"after_binding_revision" json:"after_binding_revision"`
	BeforeConnectionRevision    int64              `bson:"before_connection_revision" json:"before_connection_revision"`
	BeforeConfigRevision        int64              `bson:"before_config_revision" json:"before_config_revision"`
	BeforeStateRevision         int64              `bson:"before_state_revision" json:"before_state_revision"`
	AfterConfigRevision         int64              `bson:"after_config_revision" json:"after_config_revision"`
	Phase                       string             `bson:"phase" json:"phase"`
	PublicConfigBeforeSHA256    string             `bson:"public_config_before_sha256" json:"public_config_before_sha256"`
	PublicConfigCandidateSHA256 string             `bson:"public_config_candidate_sha256" json:"public_config_candidate_sha256"`
	ApprovalRefs                map[string]string  `bson:"approval_refs" json:"approval_refs"`
	EnableRequestID             string             `bson:"enable_request_id,omitempty" json:"enable_request_id,omitempty"`
	EnableInputSHA256           string             `bson:"enable_input_sha256,omitempty" json:"enable_input_sha256,omitempty"`
	EnableBeforeConfigRevision  int64              `bson:"enable_before_config_revision,omitempty" json:"enable_before_config_revision,omitempty"`
	EnableBeforeStateRevision   int64              `bson:"enable_before_state_revision,omitempty" json:"enable_before_state_revision,omitempty"`
	EnablePhase                 string             `bson:"enable_phase,omitempty" json:"enable_phase,omitempty"`
	EnableCandidateSHA256       string             `bson:"enable_candidate_sha256,omitempty" json:"enable_candidate_sha256,omitempty"`
}
